WITH pf AS (SELECT intDiv(k, 4) AS pid, groupArray(k % 4) AS pks, groupArray(v[1]) AS pvs FROM (SELECT groupArraySortedMapIfMerge(1)(shape_proofs) AS p FROM bestiary_mobs FINAL WHERE capture_id NOT IN (SELECT capture_id FROM capture_trust FINAL WHERE trust = 'flagged')) ARRAY JOIN mapKeys(p) AS k, mapValues(p) AS v WHERE notEmpty(v) GROUP BY pid) SELECT f.* REPLACE (arrayMap(l -> arrayMap(x -> [x.1], l), f.reach) AS reach), arrayMap(k -> if(has(pf.pks, k), pf.pvs[indexOf(pf.pks, k)], NULL), [0, 1, 2, 3]) AS proofs FROM tp_move_figures(move = 0) f LEFT JOIN pf ON pf.pid = f.id ORDER BY id
